pub(super) fn build_preconditioner(
    matrix: &CsrMatrix<Complex64>,
    kind: FemPreconditionerKind,
    ilut_config: &IlutConfig,
    k: f64,
    geometric_partitions: Option<&[Vec<usize>]>,
) -> FemPreconditioner {
    match kind {
        FemPreconditionerKind::Ilut => FemPreconditioner::Ilut(
            IlutPreconditioner::from_csr_with_config(matrix, ilut_config),
        ),
        FemPreconditionerKind::BlockJacobi => FemPreconditioner::BlockJacobi(
            BlockJacobiPreconditioner::from_csr_auto(matrix, ilut_config.clone()),
        ),
        FemPreconditionerKind::AdditiveSchwarz => FemPreconditioner::AdditiveSchwarz(
            AdditiveSchwarzPreconditioner::from_csr_auto(matrix, SCHWARZ_OVERLAP),
        ),
        FemPreconditionerKind::Oras => {
            let preconditioner = geometric_partitions.map_or_else(
                || AdditiveSchwarzPreconditioner::from_csr_oras_auto(matrix, SCHWARZ_OVERLAP, k),
                |partitions| {
                    AdditiveSchwarzPreconditioner::from_csr_partitions(
                        matrix,
                        partitions,
                        SCHWARZ_OVERLAP,
                    )
                },
            );
            FemPreconditioner::Oras(preconditioner)
        }
        FemPreconditionerKind::Habc => {
            let preconditioner = geometric_partitions.map_or_else(
                || AdditiveSchwarzPreconditioner::from_csr_habc_auto(matrix, SCHWARZ_OVERLAP, k),
                |partitions| {
                    AdditiveSchwarzPreconditioner::from_csr_partitions(
                        matrix,
                        partitions,
                        SCHWARZ_OVERLAP,
                    )
                },
            );
            FemPreconditioner::Oras(preconditioner)
        }
        FemPreconditionerKind::SweepingSchwarz => {
            // Geometric x-ordered slabs when the mesh provides them;
            // otherwise contiguous index slabs. Contiguous slabs carry
            // no wave-propagation ordering, so the sweep degrades to
            // an ordered multiplicative Schwarz still stronger than
            // the additive combination on the same partition.
            let preconditioner = geometric_partitions.map_or_else(
                || {
                    let count =
                        AdditiveSchwarzPreconditioner::<Complex64>::recommended_subdomain_count(
                            matrix.num_rows,
                        )
                        .max(1);
                    let layers: Vec<Vec<usize>> = (0..matrix.num_rows)
                        .collect::<Vec<_>>()
                        .chunks(matrix.num_rows.div_ceil(count))
                        .map(<[usize]>::to_vec)
                        .collect();
                    SweepingSchwarzPreconditioner::from_csr_layers(
                        matrix,
                        &layers,
                        SCHWARZ_OVERLAP,
                        k,
                    )
                },
                |partitions| {
                    SweepingSchwarzPreconditioner::from_csr_layers(
                        matrix,
                        partitions,
                        SCHWARZ_OVERLAP,
                        k,
                    )
                },
            );
            FemPreconditioner::SweepingSchwarz(preconditioner)
        }
        FemPreconditionerKind::IluColoring => {
            FemPreconditioner::IluColoring(IluColoringPreconditioner::from_csr(matrix))
        }
        FemPreconditionerKind::IluFixedPoint => FemPreconditioner::IluFixedPoint(
            IluFixedPointPreconditioner::from_csr(matrix, ILU_FIXED_POINT_ITERATIONS),
        ),
        FemPreconditionerKind::Amg => FemPreconditioner::Amg(Box::new(
            AmgPreconditioner::from_csr(matrix, shifted_laplacian_amg_config()),
        )),
    }
}

pub(super) fn build_recycle_subspaces(
    recycle_subspace_size: usize,
    recycler: RecyclerKind,
    n_sources: usize,
) -> Option<Vec<FemRecycleSubspace>> {
    if recycle_subspace_size == 0 {
        return None;
    }
    // Keep the legacy selector parseable for persisted configurations, but
    // execute the supported GCRO-DR algorithm in both cases. The deprecated
    // one-shot recycled-GMRES path loses its subspace benefit across Arnoldi
    // iterations and is retained only in the solver crate's compatibility API.
    let v: Vec<FemRecycleSubspace> = (0..n_sources)
        .map(|_| {
            let _compatibility_selector = recycler;
            FemRecycleSubspace(GcroDrSubspace::new(recycle_subspace_size))
        })
        .collect();
    Some(v)
}

/// Build the same full-domain tetrahedral room mesh used by
/// `run_fem_full_domain_with_mesh_report`.
pub fn build_full_domain_room_mesh(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<Mesh> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    anyhow::ensure!(
        !simulation.frequencies.is_empty(),
        "FEM mesh export requires at least one frequency"
    );
    let max_freq = simulation
        .frequencies
        .iter()
        .cloned()
        .fold(f64::NEG_INFINITY, f64::max);
    let min_wavelength = simulation.speed_of_sound / max_freq;
    let elements_per_meter = (mesh_config.elements_per_wavelength / min_wavelength).ceil() as usize;
    Ok(create_room_mesh(
        simulation,
        elements_per_meter,
        &SymmetryConfig::none(),
        mesh_config,
    ))
}

/// Build a non-uniform 1D coordinate vector on `[0, length]` with fine spacing
/// `h_fine` within `radius` of any POI and coarsening up to `h_coarse` far away.
/// Endpoints are exactly 0 and `length`. With `h_coarse <= h_fine` (or no POIs),
/// falls back to a uniform partition.
pub(super) fn build_axis_coords(
    length: f64,
    h_fine: f64,
    h_coarse: f64,
    pois: &[f64],
    radius: f64,
) -> Vec<f64> {
    debug_assert!(length > 0.0 && h_fine > 0.0);

    if h_coarse <= h_fine * 1.05 || pois.is_empty() {
        let n = (length / h_fine).ceil().max(1.0) as usize + 1;
        return (0..n).map(|i| i as f64 * length / (n - 1) as f64).collect();
    }

    // Target spacing ramps linearly from h_fine at distance `radius` to h_coarse
    // at distance `radius + transition` from the nearest POI.
    let transition = (h_coarse - h_fine).max(h_fine) * 4.0;
    let target_h = |x: f64| -> f64 {
        let mut min_dist = f64::INFINITY;
        for &p in pois {
            let d = (x - p).abs();
            if d < min_dist {
                min_dist = d;
            }
        }
        if min_dist <= radius {
            h_fine
        } else {
            let t = ((min_dist - radius) / transition).clamp(0.0, 1.0);
            h_fine + (h_coarse - h_fine) * t
        }
    };

    // Greedy walk with bounded growth/shrink ratio for smoothness.
    let max_ratio = 1.3_f64;
    let mut coords = vec![0.0_f64];
    let mut last_h = target_h(0.0);
    loop {
        let x = *coords.last().unwrap();
        let remaining = length - x;
        if remaining <= last_h * 1.5 {
            break;
        }
        let h_t = target_h(x);
        let h = h_t.clamp(last_h / max_ratio, last_h * max_ratio);
        coords.push(x + h);
        last_h = h;
    }
    coords.push(length);

    // Smooth the final interval if it's much shorter than the previous one
    // (the early-exit test can leave a small leftover).
    let n = coords.len();
    if n >= 3 {
        let last_interval = coords[n - 1] - coords[n - 2];
        let prev_interval = coords[n - 2] - coords[n - 3];
        if last_interval < 0.4 * prev_interval {
            coords.remove(n - 2);
        }
    }
    coords
}

pub(super) fn build_source_rhs_basis(
    mesh: &Mesh,
    source: &Source,
    image_walls_aabb: ([f64; 3], [f64; 3]),
    source_width: f64,
) -> SourceRhsBasis {
    let n_dofs = mesh.num_nodes();
    let n_elems = mesh.num_elements();
    let cutoff = SOURCE_TRUNCATION_SIGMAS * source_width;
    let cutoff_sq = cutoff * cutoff;
    let source_positions = image_positions(source.position, image_walls_aabb, cutoff);

    let two_sigma_sq = 2.0 * source_width * source_width;
    let norm = 1.0 / ((std::f64::consts::PI * two_sigma_sq).powf(1.5));
    let scale_base = AIR_DENSITY * SOURCE_VOLUME_VELOCITY_REFERENCE * norm;

    let combined: Vec<(usize, f64)> = (0..n_elems)
        .into_par_iter()
        .fold(Vec::new, |mut acc, elem_idx| {
            let elem = &mesh.elements[elem_idx];
            let elem_type = elem.element_type;
            let vertices = elem.vertices();
            let n_nodes = vertices.len();

            let quad = for_mass(elem_type, 1);

            let coords: Vec<[f64; 3]> = vertices
                .iter()
                .map(|&v| [mesh.nodes[v].x, mesh.nodes[v].y, mesh.nodes[v].z])
                .collect();

            let any_near = source_positions
                .iter()
                .any(|sp| point_aabb_distance_sq(*sp, &coords) <= cutoff_sq);
            if !any_near {
                return acc;
            }

            for qp in quad.iter() {
                let shape = evaluate_shape(
                    elem_type,
                    PolynomialDegree::P1,
                    qp.xi(),
                    qp.eta(),
                    qp.zeta(),
                );
                let jac = Jacobian::from_3d(&shape.gradients, shape.grad_dim, &coords);

                let x: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[0])
                    .sum();
                let y: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[1])
                    .sum();
                let z: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[2])
                    .sum();

                let mut env_sum = 0.0;
                for sp in &source_positions {
                    let dx = x - sp.x;
                    let dy = y - sp.y;
                    let dz = z - sp.z;
                    let r2 = dx * dx + dy * dy + dz * dz;
                    env_sum += (-r2 / two_sigma_sq).exp();
                }
                if env_sum == 0.0 {
                    continue;
                }

                let det_j = jac.det.abs();
                for (i, &vertex) in vertices.iter().enumerate().take(n_nodes) {
                    let weight = env_sum * shape.values[i] * det_j * qp.weight;
                    if weight.abs() > 1e-18 {
                        acc.push((vertex, weight));
                    }
                }
            }

            acc
        })
        .reduce(Vec::new, |mut a, b| {
            if a.is_empty() {
                b
            } else if b.is_empty() {
                a
            } else {
                a.extend(b);
                a
            }
        });

    let mut dense = vec![0.0; n_dofs];
    for (node_idx, val) in combined {
        dense[node_idx] += val;
    }
    let entries = dense
        .into_iter()
        .enumerate()
        .filter(|(_, val)| val.abs() > 1e-18)
        .map(|(node_idx, weight)| {
            let point = &mesh.nodes[node_idx];
            (node_idx, weight, Point3D::new(point.x, point.y, point.z))
        })
        .collect();

    SourceRhsBasis {
        entries,
        scale_base,
    }
}

/// Discrete-delta source basis: distribute the unit monopole over the
/// containing tetrahedron's nodes with its P1 shape-function values at the
/// source point.
///
/// The weights sum to one on any mesh, so the integrated source strength
/// equals the prescribed volume velocity independent of mesh density and
/// frequency. Unlike the fixed-width Gaussian of [`build_source_rhs_basis`],
/// a point load does not multiply the broadband monopole response by
/// exp(-(kσ)²/2), and it needs no near-wall mirror-image compensation
/// because nothing is truncated at the boundary.
pub(super) fn build_point_source_rhs_basis(mesh: &Mesh, source: &Source) -> Result<SourceRhsBasis> {
    let scale_base = AIR_DENSITY * SOURCE_VOLUME_VELOCITY_REFERENCE;
    let entries = find_containing_element_parallel(mesh, source.position)
        .and_then(|elem_idx| {
            let elem = &mesh.elements[elem_idx];
            let vertices = elem.vertices();
            if vertices.len() != 4 {
                return None;
            }
            let bary = compute_barycentric_coords(
                source.position,
                &mesh.nodes[vertices[0]],
                &mesh.nodes[vertices[1]],
                &mesh.nodes[vertices[2]],
                &mesh.nodes[vertices[3]],
            )?;
            Some(
                vertices
                    .iter()
                    .zip(bary.iter())
                    .filter(|(_, weight)| weight.abs() > 1.0e-15)
                    .map(|(&node, &weight)| {
                        let point = &mesh.nodes[node];
                        (node, weight, Point3D::new(point.x, point.y, point.z))
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .ok_or_else(|| {
            anyhow::anyhow!(
                "point source '{}' at {:?} lies outside the FEM mesh; refusing to assemble an empty (zero-field) RHS",
                source.name,
                source.position
            )
        })?;
    Ok(SourceRhsBasis {
        entries,
        scale_base,
    })
}

/// Build the source basis selected by the FEM configuration.
///
/// CPU and GPU runners share the same host-side source coefficients, so a
/// backend must not silently fall back to the historical Gaussian when the
/// configured model is the production PointLoad.
pub(super) fn build_source_rhs_basis_for_model(
    mesh: &Mesh,
    source: &Source,
    image_walls_aabb: ([f64; 3], [f64; 3]),
    source_model: FemSourceModel,
) -> Result<SourceRhsBasis> {
    match source_model {
        FemSourceModel::Gaussian { sigma } => Ok(build_source_rhs_basis(
            mesh,
            source,
            image_walls_aabb,
            sigma,
        )),
        FemSourceModel::PointLoad => build_point_source_rhs_basis(mesh, source),
    }
}

pub(super) fn build_listener_interpolations(
    mesh: &Mesh,
    points: &[Point3D],
    containing_elements: &[Option<usize>],
) -> (Vec<ListenerInterpolation>, usize) {
    assert_eq!(
        points.len(),
        containing_elements.len(),
        "listener interpolation input length mismatch"
    );

    let mut fallback_count = 0usize;
    let interpolations = points
        .iter()
        .zip(containing_elements.iter())
        .map(|(&point, &elem_opt)| {
            if let Some(elem_idx) = elem_opt {
                let elem = &mesh.elements[elem_idx];
                let vertices = elem.vertices();

                if vertices.len() == 4 {
                    let v0 = &mesh.nodes[vertices[0]];
                    let v1 = &mesh.nodes[vertices[1]];
                    let v2 = &mesh.nodes[vertices[2]];
                    let v3 = &mesh.nodes[vertices[3]];

                    if let Some(bary) = compute_barycentric_coords(point, v0, v1, v2, v3) {
                        return ListenerInterpolation {
                            nodes: [vertices[0], vertices[1], vertices[2], vertices[3]],
                            weights: bary,
                        };
                    }
                }
            }

            fallback_count += 1;
            log::warn!(
                "listener at ({:.3}, {:.3}, {:.3}) is outside any mesh element; using nearest-node fallback",
                point.x,
                point.y,
                point.z
            );

            let mut min_dist = f64::MAX;
            let mut nearest_node = 0;

            for (i, node) in mesh.nodes.iter().enumerate() {
                let dist = (node.x - point.x).powi(2)
                    + (node.y - point.y).powi(2)
                    + (node.z - point.z).powi(2);
                if dist < min_dist {
                    min_dist = dist;
                    nearest_node = i;
                }
            }

            ListenerInterpolation {
                nodes: [nearest_node; 4],
                weights: [1.0, 0.0, 0.0, 0.0],
            }
        })
        .collect();
    (interpolations, fallback_count)
}
